head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > refreshRow]<br/>Body Row 의 인덱스를 사용하여 특정 Body Row 에 CSS 클래스를 설정합니다.",
    "validation" : [
        "rowIndex(필수) 파라미터는 Body 가 MultiLine 일때 각 Line 의 Row 인덱스값은 같습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Body Row MultiLine 구성)
//  - gBody 에 <w2:row> 2개 -> 한 데이터 Row 가 2 Line 으로 표시됨
//  - 1줄 = col1(지점명, 인덱스0) / col2(매출, 인덱스1), 2줄 = col3(담당자, 인덱스2) / col4(연락처, 인덱스3)
//  - Body 가 MultiLine 이어도 한 데이터 Row 의 두 line 은 동일한 rowIndex 를 가짐
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // MultiLine 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body 가 MultiLine(한 데이터 Row 가 2줄). 1줄 col1(지점명)/col2(매출), 2줄 col3(담당자)/col4(연락처). 데이터 Row 3개. MultiLine 이어도 한 데이터 Row 의 두 line 은 동일한 rowIndex(0~2) 를 가짐.\n[절차] 1) (GridView 값만 수정) 클릭 -> 모든 Row 2줄 표시 셀 화면(DOM) 값만 임시 변경(DataList 미반영 -> 화면과 DataList 불일치). 2) rowIndex(0~2) 선택 후 (refreshRow 실행) -> refreshRow(rowIndex) 한 번 호출.\n[확인] refreshRow(데이터 Row 인덱스) 한 번에 그 Row 의 2개 line 전체 셀(col1~col4)이 DataList 원본값으로 복원됨. 선택하지 않은 Row 는 임시값 유지. 두 line 모두 동일 rowIndex 임을 반환영역에서 확인."', '', 'label1');

    // dataList 생성 + 초기값 바인딩 (col1~col4)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "서울 강남점", "col2": "1250", "col3": "김영업", "col4": "010-1111-2222" },
        { "col1": "부산 해운대점", "col2": "980", "col3": "이판매", "col4": "010-3333-4444" },
        { "col1": "대구 수성점", "col2": "1430", "col3": "박상담", "col4": "010-5555-6666" }
    ]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (Body Row MultiLine : gBody 에 <w2:row> 2개)
    //  - 1줄 : col1(지점명, 0) / col2(매출, 1)
    //  - 2줄 : col3(담당자, 2) / col4(연락처, 3)
    //  - 한 데이터 Row 의 두 line 은 동일한 rowIndex 를 가짐
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:560px;height:340px;">';
    strTarget += '<w2:caption style="" id="caption1" value="refreshRow 테스트 그리드 (MultiLine)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol1" value="지점명"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol2" value="매출(만원)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol3" value="담당자"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="연락처"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // 1줄 : col1(지점명, 0) / col2(매출, 1)
    strTarget += '<w2:column width="280" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    // 2줄 : col3(담당자, 2) / col4(연락처, 3)
    strTarget += '<w2:column width="280" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// [1단계] GridView 화면 값만 수정 : DataList 는 건드리지 않고 그리드 셀의 화면(DOM) 표시값만 임시로 변경한다.
//  -> MultiLine Row 의 모든 셀(전체 Row x col1~col4) 화면값을 임시값으로. refreshRow 가 DataList 를 다시 읽어 화면을 복원하는지 확인용.
scwin.btn_modifyAllCells_onclick = function () {
    let cnt = dlt_bind.getRowCount();
    let colCnt = target1.getColumnCount();

    // 화면에만 표시할 임시값 : 초기값과 같은 형태(지점명/매출/담당자/연락처)지만 다른 값
    let fakeMap = {
        "col1": ["인천 부평점", "대전 둔산점", "울산 남구점"],
        "col2": ["1530", "2040", "870"],
        "col3": ["최영업", "정판매", "강상담"],
        "col4": ["010-7777-8888", "010-9999-0000", "010-2222-3333"]
    };

    // 모든 표시 셀의 화면(td) 텍스트만 임시값으로 변경 (DataList 미반영)
    //  - MultiLine 이어도 한 데이터 Row 의 두 line 셀은 동일 rowIndex(r) 를 가지며 col1~col4 는 고유 인덱스(0~3)
    for (let r = 0; r < cnt; r++) {
        for (let c = 0; c < colCnt; c++) {
            let td = document.querySelector("td[id*='target1_cell_" + r + "_" + c + "']");
            if (!td) { continue; }
            let colID = target1.getColumnID(c);
            let val = (fakeMap[colID] && typeof fakeMap[colID][r] !== 'undefined') ? fakeMap[colID][r] : ("임시" + r);
            td.textContent = val;
        }
    }

    wf_body_bottom.getObj("scwin").setReturnValue("GridView 화면 값만 수정 완료 (DataList 미반영). 모든 Row 2줄(col1~col4) 화면값이 임시값으로 바뀌었지만 DataList 는 원본 유지 -> rowIndex(0~2) 선택 후 (refreshRow 실행) 으로 해당 Row 2줄 복원 확인.");
}

// [2단계] refreshRow 실행 : 선택 Row(데이터 Row 인덱스) 를 DataList 값으로 다시 렌더링한다.
//  -> refreshRow(rowIndex) 한 번 호출로 그 Row 의 2개 line 전체 셀(col1~col4)이 DataList 원본으로 복원된다.
//  -> MultiLine 이어도 두 line 은 동일한 rowIndex 를 가지므로 한 번 호출로 양쪽 line 이 모두 복원된다. (선택 안 한 Row 는 임시값 유지)
scwin.btn_refreshRow_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let colCnt = target1.getColumnCount();

    // refreshRow 를 rowIndex 로 호출 -> DataList 값을 다시 읽어 해당 Row(2줄) 전체 화면 복원
    target1.refreshRow(rowIndex);

    // 복원된 해당 데이터 Row 의 양쪽 line 셀 표시값을 모두 수집 (1줄 col1/col2, 2줄 col3/col4)
    let line1 = [];
    let line2 = [];
    for (let c = 0; c < colCnt; c++) {
        let colID = target1.getColumnID(c);
        let td = document.querySelector("td[id*='target1_cell_" + rowIndex + "_" + c + "']");
        let txt = td ? td.textContent.trim() : '';
        // col1/col2 는 1줄, col3/col4 는 2줄
        if (colID === "col1" || colID === "col2") {
            line1.push(colID + "=" + txt);
        } else {
            line2.push(colID + "=" + txt);
        }
    }

    wf_body_bottom.getObj("scwin").setReturnValue("refreshRow(" + rowIndex + ") -> 동일 rowIndex 로 2줄 모두 DataList 원본 복원 | 1줄 : " + line1.join(', ') + " | 2줄 : " + line2.join(', '));
}
